@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Press+Start+2P&display=swap');
:root{color-scheme:dark;--gold:#ffd978;--cream:#fff3d4;--ink:#131522;--muted:#a9a9b5}
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101524;color:var(--cream);font-family:'DM Mono',monospace;touch-action:none}
body{display:grid;place-items:center;background:radial-gradient(ellipse at 50% 35%,#28334a 0,#111726 55%,#090c15 100%)}
button{font:inherit;color:inherit}
.game-shell{position:relative;width:min(100vw,177.78vh);height:min(100vh,56.25vw);max-width:1280px;max-height:720px;overflow:hidden;background:#101524;box-shadow:0 24px 100px #000b;border:1px solid #ffffff20}
.game-shell:after{content:"";pointer-events:none;position:absolute;inset:0;box-shadow:inset 0 0 70px #080b1680;z-index:5}
.scene{position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated;image-rendering:crisp-edges}
.hud{position:absolute;inset:0;z-index:8;pointer-events:none}
.brand{position:absolute;left:25px;top:21px;text-shadow:0 2px 3px #101016}
.brand b{font:10px 'Press Start 2P';color:var(--gold);letter-spacing:1px}
.brand small{display:block;color:#d4d2cc;font-size:9px;letter-spacing:2px;margin-top:8px}
.status{position:absolute;top:20px;right:22px;display:flex;align-items:flex-start;gap:12px}
.meterbox,.questbox{background:#121522df;border:1px solid #ffffff28;box-shadow:0 4px 12px #0005;padding:9px 11px}
.meterbox{width:128px}
.label{font-size:8px;color:#c5c2c1;letter-spacing:1px}
.hearts{margin-top:7px;display:flex;gap:4px}
.heart{height:8px;flex:1;background:#e45557;box-shadow:inset 0 -2px #9d3139}
.heart.empty{background:#373442;box-shadow:none}
.xpbar{height:5px;margin-top:6px;background:#282c3a}
.xpbar i{display:block;height:100%;width:0;background:#f1c95d;transition:width .3s}
.questbox{width:188px}
.questbox strong{font:7px 'Press Start 2P';display:block;color:var(--gold);margin:7px 0 5px;line-height:1.8}
.questbox span{font-size:9px;color:#d6d1c6;line-height:1.45;display:block}
.zone{position:absolute;left:50%;top:20px;transform:translateX(-50%);text-align:center;text-shadow:0 2px 4px #151524}
.zone b{font:9px 'Press Start 2P';color:#fff1cc}
.zone small{display:block;color:#e3ddcf;font-size:9px;letter-spacing:2px;margin-top:8px}
.hint{position:absolute;bottom:15px;left:50%;transform:translateX(-50%);padding:8px 13px;background:#131522c9;border:1px solid #ffffff22;font-size:9px;color:#eee0c2;white-space:nowrap;transition:opacity .4s}
.hint kbd{color:#ffd978;font-weight:bold}
.sound{pointer-events:auto;position:absolute;right:22px;bottom:18px;border:1px solid #ffffff32;background:#141725d9;width:34px;height:34px;cursor:pointer;font-size:15px}
.mobile-controls{display:none;pointer-events:auto;position:absolute;left:0;right:0;bottom:12px;height:130px}
.pad{position:absolute;left:18px;bottom:0;width:136px;height:126px}
.ctrl{position:absolute;width:43px;height:43px;border:1px solid #ffffff55;background:#181b2bc9;color:#fff4d2;font-size:17px;border-radius:8px;display:grid;place-items:center;user-select:none;-webkit-user-select:none;touch-action:none;box-shadow:inset 0 1px #ffffff20}
.ctrl:active,.ctrl.down{background:#d39c4dcc}
.up{left:46px;top:0}
.down{left:46px;bottom:0}
.left{left:0;top:42px}
.right{right:0;top:42px}
.action{position:absolute;right:26px;bottom:12px;width:70px;height:70px;border-radius:50%;font-size:10px;font-weight:bold;letter-spacing:1px;background:#ac473dd9;border-color:#ffb48a77}
.dash{right:103px;bottom:0;width:48px;height:48px;border-radius:50%;font-size:9px;background:#556b83dc}
.veil{position:absolute;inset:0;z-index:12;background:linear-gradient(180deg,#131629a6,#101321d9);display:grid;place-items:center;transition:opacity .5s}
.veil.hidden{opacity:0;pointer-events:none}
.card{width:min(510px,90%);text-align:center;padding:35px 36px;background:#171a2beF;border:1px solid #f1ce7b55;box-shadow:0 20px 70px #0009;position:relative}
.card:before,.card:after{content:'✦';position:absolute;color:#ffd978;font-size:18px;top:14px}
.card:before{left:16px}
.card:after{right:16px}
.eyebrow{font-size:9px;letter-spacing:3px;color:#ffcf74}
.title{font:clamp(20px,4vw,32px)/1.5 'Press Start 2P';margin:15px 0;color:#fff0c8;text-shadow:3px 4px #7f3b48}
.title em{font-style:normal;color:#ffb35a}
.intro{font-size:11px;line-height:1.9;color:#d3d0d0;max-width:400px;margin:0 auto 20px}
.start{border:0;background:#e5b857;color:#241a24;padding:13px 22px;font:10px 'Press Start 2P';cursor:pointer;box-shadow:0 4px #9b673c}
.start:hover{background:#ffda79;transform:translateY(-1px)}
.card .foot{font-size:8px;color:#9da0ae;margin-top:20px;line-height:1.8}
.toast{position:absolute;z-index:10;left:50%;top:28%;transform:translate(-50%,-10px);padding:12px 20px;background:#171a2bea;border:1px solid #ffd97888;color:#ffe4a0;font-size:10px;opacity:0;transition:.3s;pointer-events:none;text-align:center;line-height:1.6}
.toast.show{opacity:1;transform:translate(-50%,0)}
.touch-tip{display:none}
.gamepad-hint{display:none}
@media (pointer:coarse),(max-width:760px){.mobile-controls{display:block}
.hint{bottom:145px}
.brand{left:12px;top:12px}
.brand b{font-size:7px}
.brand small{font-size:7px;margin-top:5px}
.status{right:9px;top:9px;gap:5px}
.meterbox{width:86px;padding:6px}
.questbox{width:130px;padding:6px}
.label{font-size:7px}
.questbox strong{font-size:6px;margin:4px 0}
.questbox span{font-size:7px}
.zone{top:auto;bottom:154px}
.zone b{font-size:7px}
.zone small{font-size:7px;margin-top:5px}
.sound{display:none}
.card{padding:27px 20px}
.intro{font-size:10px}
.touch-tip{display:block}
